LAYOUT_B64 = ''
# Restyle the three.js studio render into a cinematic 3D-animation look while keeping its layout.
# A) SDXL img2img at two strengths. B) SDXL + ControlNet (canny edges of the render).
# Models: SDXL 1.0 base and diffusers/controlnet-canny-sdxl-1.0 (both CreativeML OpenRAIL++-M, commercial use allowed).
import subprocess, time, os, io, base64
t0 = time.time()
subprocess.run("pip install -q -U diffusers transformers accelerate opencv-python-headless", shell=True, timeout=900)
import torch, numpy as np, cv2
from PIL import Image, ImageDraw
from diffusers import (StableDiffusionXLImg2ImgPipeline, StableDiffusionXLControlNetPipeline,
                       ControlNetModel, AutoencoderKL)
LAYOUT = Image.open(io.BytesIO(base64.b64decode(LAYOUT_B64))).convert("RGB")
W, H = LAYOUT.size
P1 = ("cozy podcast studio set, two blue velvet armchairs with yellow cushions facing each other, small round "
      "wooden table with two gold podcast microphones, headphones and a mug, two black pendant lamps glowing warm")
P2 = ("Pixar-style 3D animated movie still, cinematic lighting, deep navy velvet curtains with soft folds, "
      "glowing yellow LED strip along the curved stage edge, soft global illumination, rich textures, high detail")
NEG = "text, letters, logo, watermark, people, person, character, windows, desk, computer, blurry, lowres, deformed"
vae = AutoencoderKL.from_pretrained("madebyollin/sdxl-vae-fp16-fix", torch_dtype=torch.float16)
out = []
i2i = StableDiffusionXLImg2ImgPipeline.from_pretrained("stabilityai/stable-diffusion-xl-base-1.0", vae=vae,
      torch_dtype=torch.float16, variant="fp16", use_safetensors=True).to("cuda")
for strength in [0.45, 0.6]:
    for seed in [1, 2]:
        img = i2i(prompt=P1, prompt_2=P2, negative_prompt=NEG, image=LAYOUT, strength=strength,
                  num_inference_steps=40, guidance_scale=7.0, generator=torch.Generator("cuda").manual_seed(seed)).images[0]
        name = f"repaint_s{int(strength*100)}_seed{seed}"; img.save(f"/kaggle/working/{name}.png"); out.append((name, img))
        print(name, f"{time.time()-t0:.0f}s", flush=True)
del i2i; torch.cuda.empty_cache()
edges = cv2.Canny(np.array(LAYOUT), 60, 160)
edges = Image.fromarray(np.stack([edges] * 3, -1)); edges.save("/kaggle/working/layout_edges.png")
cn = ControlNetModel.from_pretrained("diffusers/controlnet-canny-sdxl-1.0", torch_dtype=torch.float16)
pipe = StableDiffusionXLControlNetPipeline.from_pretrained("stabilityai/stable-diffusion-xl-base-1.0", vae=vae,
       controlnet=cn, torch_dtype=torch.float16, variant="fp16", use_safetensors=True).to("cuda")
for seed in [1, 2]:
    img = pipe(prompt=P1, prompt_2=P2, negative_prompt=NEG, image=edges, controlnet_conditioning_scale=0.6,
               width=W, height=H, num_inference_steps=36, guidance_scale=7.0,
               generator=torch.Generator("cuda").manual_seed(seed)).images[0]
    name = f"edges_seed{seed}"; img.save(f"/kaggle/working/{name}.png"); out.append((name, img))
    print(name, f"{time.time()-t0:.0f}s", flush=True)
cols, tw, th = 3, W // 2, H // 2
rows = (len(out) + 1 + cols - 1) // cols
sheet = Image.new("RGB", (tw * cols, (th + 30) * rows), "white"); d = ImageDraw.Draw(sheet)
for k, (name, im) in enumerate([("layout (three.js)", LAYOUT)] + out):
    x, y = (k % cols) * tw, (k // cols) * (th + 30)
    d.text((x + 10, y + 8), name, fill="black"); sheet.paste(im.resize((tw, th)), (x, y + 30))
sheet.save("/kaggle/working/restyle_options.jpg", quality=90)
print(f"TOTAL {time.time()-t0:.0f}s")
